// Synthetic replica of lottie-react-native@7 sources (TSX). Renders a native
// animation view registered off the React Native default export.
import ReactNative from "react-native";

const AnimationNativeView =
  (ReactNative as { requireNativeComponent?: (name: string) => unknown }).requireNativeComponent?.(
    "LottieAnimationView",
  ) ?? "LottieAnimationView";

export const LOTTIE_OK = "LOTTIE_OK";

export type LottieViewProps = {
  source: object | string;
  autoPlay?: boolean;
  loop?: boolean;
};

export default function LottieView(props: LottieViewProps) {
  return (
    <AnimationNativeView
      sourceJson={typeof props.source === "string" ? props.source : JSON.stringify(props.source)}
      autoPlay={props.autoPlay ?? false}
      loop={props.loop ?? true}
    />
  );
}
